TIER_LOW={
1:("rank-1 consort (Đáp ứng), the lowest consort rank, elegant, never poor","a fine silk robe with delicate embroidered {motif} at the collar, sleeves and hem and a soft silk sash","a neat bun with pretty silver hairpins and a fresh flower ({flower})","little gold"),
2:("rank-2 consort (Thường tại), a little more ornate than the lowest rank","a fine silk robe with embroidered borders and a small woven {motif} pattern","a neat chignon with silver and pearl hairpins and a fresh flower ({flower})","little gold"),
3:("rank-3 consort (Quý nhân), richer than the ranks below","a patterned silk robe with small woven {motif}","a layered chignon with fresh flower hairpins ({flower}) and small silk flowers","little gold")}
FAB_LOW="Light, soft, thin flowing silk: the long sleeves, skirt and sash are supple and airy, drifting softly as in a gentle breeze, with soft natural folds, never stiff, flat or board-like."
def outfit_low123(c,t,pal,main):
    rk,robe,hair,gold=TIER_LOW[t]; mo,fl=MOTIF_LOW[c]
    return f"Outfit ({rk}): a NEW outfit, {robe.format(motif=mo)}; {hair.format(flower=fl)}; her signature colour family {pal} stays the MAIN robe colour ({main}, NOT green); the robe itself is clearly {main} silk, {gold}, NOT a cream, beige or all-gold robe"
ITEMS_LOW={"c06":{1:("a plain silk round fan with a bamboo handle","two"),2:("an embroidered silk sachet with a tassel","one"),3:("an embroidered silk round fan with a silk tassel","two"),
 4:("a round fan with a carved jade handle and jade tassel","two"),5:("a round fan with a gold-inlaid handle and gem tassel","two"),6:("a white-jade ruyi","one")},
 "c25":{1:("a sprig of fresh plum blossoms","one"),2:("a painted paper folding fan","one"),3:("a painted scroll with wooden rollers","scroll"),
 4:("a lacquered jewel box","box"),5:("a painted scroll with gold fittings","scroll"),6:("a jewelled box","box")}}
# per-person item ladder (t1..t6) for everyone else: signature object of her jobs.json poses (phoenix-free), stepped up in richness per rank
# (B, hand key, style); styles: trim (default) | jade | pearls | flower
LOW_SIG={"c01":("round silk fan painted with peonies","two","trim"),"c02":("round silk fan","two","trim"),"c03":("white feather fan","two","trim"),
"c04":("round gauze fan with a red tassel","two","trim"),"c05":("round fan painted with peonies","two","trim"),"c07":("silk handkerchief","one","trim"),
"c08":("embroidered sachet","one","trim"),"c09":("small white flower","one","flower"),"c10":("sprig of white jasmine","one","flower"),
"c11":("folded letter","one","trim"),"c12":("string of pearls","one","pearls"),"c13":("embroidery hoop","two","trim"),"c14":("basket of flowers","two","trim"),
"c15":("sprig of plum blossom","one","flower"),"c16":("pink lotus flower","one","flower"),"c17":("spool of silk thread and a needle case","one","trim"),
"c18":("sandalwood folding fan","two","trim"),"c19":("painted silk folding fan","two","trim"),"c20":("embroidered silk folding fan","two","trim"),
"c21":("ivory folding fan","two","trim"),"c22":("folding fan painted with butterflies","two","trim"),"c23":("carved jade token","one","jade"),
"c24":("jade ruyi sceptre","one","jade"),"c26":("jade pendant on a red cord","one","jade"),"c27":("hairpin box","box","trim"),"c28":("thread-bound book","two","trim"),
"c29":("small guqin","two","trim"),"c30":("rolled scroll","scroll","trim"),"c31":("jade flute","two","jade"),"c32":("brush and a sheet of paper","two","trim")}
def _art(s): return ("an " if s[0] in "aeiou" else "a ")+s
def low_items(c):
    B,hk,st=LOW_SIG[c]
    if st=="flower": r=[_art(f"fresh {B}"),_art(f"fresh {B}"),f"{_art('fresh '+B)} tied with a silk ribbon",f"{_art('fresh '+B)} tied with a silk ribbon and a jade bead",
        f"{_art('fresh '+B)} tied with a gold ribbon and a jade bead",f"{_art('fresh '+B)} set in a small gold-and-jade holder"]
    else:
        tr={"trim":("jade","gold","gold and gems"),"jade":("silver","gold","gold and gems"),"pearls":("a jade clasp","a gold clasp","a gold-and-gem clasp")}[st]
        w=(lambda x:f"with {x}") if st=="pearls" else (lambda x:f"trimmed with {x}")
        r=[_art(f"simple {B}"),_art(f"neat {B}"),_art(f"finely made {B}"),f"{_art('fine '+B)} {w(tr[0])}",f"{_art('fine '+B)} {w(tr[1])}",f"{_art(B)} {w(tr[2])}"]
    return {t+1:(r[t],hk) for t in range(6)}
for _c in LOW_SIG: ITEMS_LOW[_c]=low_items(_c)
LOWNAME={"c06":("vermilion","coral red"),"c25":("deep cherry red","brick rust red")}
for _c in DATA:
    if _c not in LOWNAME and _c in ORIG1: LOWNAME[_c]=(DATA[_c][0].split(" and ")[0],ORIG1[_c][0].split(" silk")[0])
YEL_T6="; a little more luxury than the rank below: richer gold-thread embroidery covering more of the robe and a slightly grander headdress with a few more gold ornaments, restrained and elegant, NOT overloaded with jewels, clearly less grand than the imperial noble consort; plus a SMALL touch of royal yellow only (a narrow royal golden yellow border or sash, or one small yellow inner panel, a honey-gold close to hex #EFBD69, 18K gold tone, not pale cream, not beige, not mustard), MUCH less yellow than an imperial noble consort's robe; COLOUR RULE:"
LUX_T6="; a little more luxury than the rank below: richer gold-thread embroidery covering more of the robe and a slightly grander headdress with a few more gold ornaments, restrained and elegant, NOT overloaded with jewels, clearly less grand than the imperial noble consort; COLOUR RULE:"
def low_outfit(c,t,v="v0"):
    if f"{c}-t{t}" in OUTFIT_LOW: o=OUTFIT_LOW[f"{c}-t{t}"]
    else:
        o=OUTFIT_JOBS[f"{c}-t{t}"]
        if t==6 and "a little more luxury" not in o: o=o.replace("; COLOUR RULE:",YEL_T6,1)
    if t==6 and v=="v1": o=o.replace(YEL_T6,LUX_T6)   # v1 already has royal yellow as the MAIN colour: no 'small touch' clause
    return o
def build_low(c,t,v="v0"):
    pal,face=DATA[c]; m,m2=ORIG1[c]; item,hk=ITEMS_LOW[c][t]; right=(int(c[1:])%2==1)
    main0,orig=LOWNAME[c]
    o=(outfit_low123(c,t,pal,main0) if t<=3 else low_outfit(c,t,v))
    # colour word of the outfit text: v0 = her ORIGINAL robe colour (skipped when the original name already contains the family word); v1 = royal yellow; v2 = V2 family
    new={"v0":orig,"v1":"royal golden yellow","v2":V2[c]}[v]
    if not (v=="v0" and main0 in orig): o=re.sub(re.escape(main0)+r"(?! blossom)",new,o)
    o=o.replace("phoenixes and peonies","peonies and small birds").replace("phoenixes and butterflies","peonies and butterflies").replace("phoenixes and bamboo leaves","peonies and bamboo leaves")
    o=re.sub(r"phoenixes and (peonies|[a-z\- ]+?) in ",lambda k:"peonies and small birds in " if k.group(1)=="peonies" else "peonies and "+k.group(1)+" in ",o)
    assert "phoenix" not in o,(c,t)
    s=PRE+f" An imperial consort. Her face: {face}. From the identity reference keep ONLY her face, facial features, hairstyle colour and signature colour family; do NOT copy the outfit, hair ornaments or accessories of the reference, dress her in the NEW outfit below. The style reference image is only for skin, drawing style, fabric and embroidery: never copy its face, body or pose. {AGE_TXT[AGE]} "+o+"."
    if v=="v0": s+=f" COLOUR RULE: all colours fresh, clear and luminous, never dusty or greyed; her ORIGINAL robe colour is kept exactly as in image 1 (her first reference): {m} is the main colour of the robe, sleeves and any cape, with {m2} in the inner robe and linings; gold only as thin accents."
    else: s+=" COLOUR RULE: "+colour(c,v,False)[0]
    hairs=" Hair: her own hairstyle as described in the outfit, with silver, pearl and fresh flowers, little gold. " if t<=3 else " Hair: her own hairstyle decorated with fresh flowers and several gold hairpins (trâm) with dangles, rich like her rank. "
    s+=hairs+"No phoenix anywhere on the robe or in the hair: only flowers, birds, butterflies or other motifs. All flowers, birds and butterflies are fine silk-thread embroidery stitched directly into the fabric, flat and integrated with the cloth, following its folds, not appliqué, not pasted patches, not raised. "+(FAB_LOW if t<=3 else FAB)
    s+=f" Pose: calm standing pose; she holds {item} in a contrasting colour, not the robe colour, the item held below the chin, the hand really gripping it, the whole face fully visible. Her hands interact naturally with the item (gently presenting, turning or touching it), lively and natural, while her head stays up facing the viewer, eyes open, lips closed, never looking down. Her hands and body: {hand7(hk if hk in ('one','two','box') else 'one',right) if hk!='scroll' else 'the scroll in one hand lowered at her side, the other hand lifting her sleeve slightly, body turned slightly three-quarters to the right'}."
    s+=" Every hairpin is inserted into the hair pointing upward or backward with dangles hanging down, no hairpin horizontal or sticking out to the side. Luminous smooth porcelain skin, bare clean forehead with no forehead mark and no flower mark, eyes open, floor-length robe with slippers visible, no train, no cup, nothing covering the face."
    return s+END
if __name__=="__main__":
    if "--age" in sys.argv: AGE=sys.argv[sys.argv.index("--age")+1]; sys.argv[sys.argv.index("--age"):sys.argv.index("--age")+2]=[]
    LOWN=None
    if "--low" in sys.argv: i=sys.argv.index("--low"); LOWN=int(sys.argv[i+1]); sys.argv[i:i+2]=["--low"]
    a=[x for x in sys.argv[1:] if not x.startswith("--")]
    print(build_low(a[0],LOWN,a[1] if len(a)>1 else "v0") if "--low" in sys.argv else build_t7(a[0],a[1] if len(a)>1 else "v0") if "--t7" in sys.argv else build(a[0],a[1] if len(a)>1 else "v0","--golden" in sys.argv),end="")
